const express = require('express');
const cookieParser = require('cookie-parser');
const { ScalekitClient } = require('@scalekit-sdk/node');

const app = express();

// Initialize Scalekit client
const scalekit = new ScalekitClient(
  process.env.SCALEKIT_ENV_URL,
  process.env.SCALEKIT_CLIENT_ID,
  process.env.SCALEKIT_CLIENT_SECRET
);

const REDIRECT_URI = 'http://localhost:3000/callback';
const POST_LOGOUT_URI = 'http://localhost:3000/goodbye';

// AgentKit fixtures
const AGENTKIT_CONNECTION = 'github-test';
const AGENTKIT_IDENTIFIER = 'zealt-user01';

app.use(cookieParser());

// ---- Helper: decode JWT payload (no verification, just base64url decode) ----
function decodeJwtPayload(token) {
  try {
    const parts = token.split('.');
    if (parts.length !== 3) return null;
    const payload = parts[1];
    // Base64url decode
    const base64 = payload.replace(/-/g, '+').replace(/_/g, '/');
    const json = Buffer.from(base64, 'base64').toString('utf8');
    return JSON.parse(json);
  } catch {
    return null;
  }
}

// ---- Helper: is authenticated ----
function isAuthenticated(req) {
  return !!(req.cookies && req.cookies.idToken);
}

// ---- GET / — Landing page ----
app.get('/', (req, res) => {
  res.send(`<!DOCTYPE html>
<html lang="en">
