});

// ---- GET /login — Redirect to Scalekit authorize URL ----
app.get('/login', (req, res) => {
  const authUrl = scalekit.getAuthorizationUrl(REDIRECT_URI, {
    scopes: ['openid', 'profile', 'email', 'offline_access'],
  });
  res.redirect(authUrl);
});

// ---- GET /callback — Exchange code for tokens ----
app.get('/callback', async (req, res) => {
  const { code, error, error_description } = req.query;

  if (error) {
    return res.status(400).send(`Authentication error: ${error} — ${error_description}`);
  }

  if (!code) {
    return res.status(400).send('Missing authorization code.');
  }

  try {
    const authResp = await scalekit.authenticateWithCode(code, REDIRECT_URI);

    // Set HttpOnly cookies
    const cookieOpts = { httpOnly: true, path: '/', secure: false, sameSite: 'lax' };
    res.cookie('accessToken', authResp.accessToken, cookieOpts);
    res.cookie('refreshToken', authResp.refreshToken, cookieOpts);
    res.cookie('idToken', authResp.idToken, cookieOpts);

    return res.redirect('/dashboard');
  } catch (err) {
    console.error('Authentication failed:', err);
    return res.status(500).send('Authentication failed. Please try again.');
  }
});

// ---- GET /dashboard — Protected dashboard with AgentKit repos ----
app.get('/dashboard', async (req, res) => {
  if (!isAuthenticated(req)) {
    return res.redirect('/login');
  }

  const idToken = req.cookies.idToken;
  const claims = decodeJwtPayload(idToken);
  const email = claims ? claims.email : 'Unknown';

  // Fetch GitHub repos via AgentKit
  let reposHtml = '<p>Loading repositories...</p>';
  try {
    // First, list scoped tools to find the GitHub list-repos tool
    const scopedTools = await scalekit.tools.listScopedTools(AGENTKIT_IDENTIFIER, {
      filter: { connectionNames: [AGENTKIT_CONNECTION] },
      pageSize: 100,
    });

    // Find the GitHub list repositories tool
    let listReposToolName = null;
    for (const scopedTool of scopedTools.tools) {
      const definition = scopedTool.tool?.definition;
      if (definition && typeof definition === 'object') {
        const name = definition.name;
        if (name && (
          name === 'github_list_repositories' ||
          name === 'github_list_repos' ||
          name === 'github_list_user_repos' ||
          name.includes('list_repo')
        )) {
          listReposToolName = name;
          break;
        }
      }
    }

    // Fallback: try common tool names
    if (!listReposToolName) {
      const toolNames = scopedTools.tools.map(t => t.tool?.definition?.name).filter(Boolean);
      // Try to find any GitHub repo-related tool
      for (const name of toolNames) {
        if (name && name.startsWith('github_') && (name.includes('repo') || name.includes('repository'))) {
          listReposToolName = name;
          break;
        }
      }
    }

    if (listReposToolName) {
      const result = await scalekit.tools.executeTool({
        toolName: listReposToolName,
        identifier: AGENTKIT_IDENTIFIER,
        connector: AGENTKIT_CONNECTION,
        params: {},
      });

      const data = result.data;
      let repos = [];

      // Handle different possible response shapes
      if (data && Array.isArray(data)) {
        repos = data;
      } else if (data && Array.isArray(data.repositories)) {
        repos = data.repositories;
      } else if (data && typeof data === 'object') {
        // Try common keys
        for (const key of ['repositories', 'repos', 'items', 'data']) {
          if (Array.isArray(data[key])) {
            repos = data[key];
            break;
          }
        }
      }

      if (repos.length > 0) {
        reposHtml = '<ul>';
        for (const repo of repos) {
          const fullName = repo.full_name || repo.fullName || repo.name || 'Unknown';
          const htmlUrl = repo.html_url || repo.htmlUrl || repo.url || '#';
          reposHtml += `<li><a href="${htmlUrl}" target="_blank">${fullName}</a></li>`;
        }
        reposHtml += '</ul>';
      } else {
        reposHtml = '<p>No repositories found.</p>';
      }
    } else {
      reposHtml = '<p>Could not find the GitHub list repositories tool. Available tools: ' +
        scopedTools.tools.map(t => t.tool?.definition?.name).filter(Boolean).join(', ') + '</p>';
    }
  } catch (err) {
    console.error('AgentKit error:', err);
    reposHtml = `<p>Error fetching repositories: ${err.message}</p>`;
  }

  res.send(`<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width, initial-scale=1.0">
  <title>Dashboard - Scalekit Demo</title>
  <style>
    body { font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif; max-width: 700px; margin: 40px auto; padding: 0 20px; }
    h1 { color: #333; }
    .email { background: #EEF2FF; padding: 12px 16px; border-radius: 6px; margin: 16px 0; }
    .email-label { font-weight: 600; color: #4F46E5; }
    ul { list-style: none; padding: 0; }
    li { padding: 10px 16px; margin: 4px 0; background: #F9FAFB; border-radius: 6px; border: 1px solid #E5E7EB; }
    li a { color: #4F46E5; text-decoration: none; font-weight: 500; }
    li a:hover { text-decoration: underline; }
    .logout-btn { display: inline-block; padding: 10px 24px; background: #DC2626; color: white; text-decoration: none; border-radius: 6px; font-size: 14px; font-weight: 500; margin-top: 24px; }
    .logout-btn:hover { background: #B91C1C; }
  </style>
</head>
<body>
  <h1>Dashboard</h1>
  <div class="email">
    <span class="email-label">Signed in as:</span> ${email}
  </div>
  <h2>GitHub Repositories</h2>
  ${reposHtml}
  <a class="logout-btn" href="/logout">Sign out</a>
</body>
</html>`);
});

